import React, { useEffect, useState } from "react";
import { Link, useSearchParams } from "react-router-dom";
import { AlertTriangle, ChevronLeft, ChevronRight, Send } from "lucide-react";
import { useAuth } from "./AuthContext";
import { useNotice } from "./NoticeContext";
import { apiFetch } from "./api";
import { h, f } from "./h";
import { Badge, Button, Field, GlassCard, GlassPanel, InlineNotice, SelectInput, TextArea, TextInput } from "./ui";
import { BuyerLayout, CartDrawer } from "./screensBuyer";

/** Match admin `REPORT_CATS` / backend enum. */
const REPORT_CATEGORIES = [
  { value: "fake_seller", label: "Fake / misleading seller" },
  { value: "scam", label: "Scam" },
  { value: "bad_product", label: "Bad product / listing" },
  { value: "chat_abuse", label: "Abuse in messages" },
  { value: "other", label: "Other" }
];

const TARGET_TYPES = [
  { value: "product", label: "Product listing" },
  { value: "user", label: "User / vendor / buyer" },
  { value: "order", label: "Order" },
  { value: "other", label: "General (no specific link)" }
];

function reportStatusTone(s) {
  if (s === "open") return "warn";
  if (s === "in_review") return "info";
  if (s === "resolved") return "success";
  if (s === "dismissed") return "neutral";
  return "neutral";
}

function fmtDate(d) {
  if (!d) return "—";
  try {
    return new Date(d).toLocaleDateString(undefined, { year: "numeric", month: "short", day: "numeric" });
  } catch {
    return "—";
  }
}

function shortId(id) {
  if (!id) return "—";
  return `#${String(id).slice(-8).toUpperCase()}`;
}

function ReportsPager({ page, total, limit, onPage }) {
  const pages = Math.max(1, Math.ceil((total || 0) / (limit || 1)));
  const start = total === 0 ? 0 : (page - 1) * limit + 1;
  const end = Math.min(page * limit, total);
  return h("div", { className: "flex flex-wrap items-center justify-between gap-3 text-xs text-slate-500 dark:text-slate-400" }, [
    h("span", { key: "t" }, `Showing ${start}-${end} of ${total} · page ${page}/${pages}`),
    h("div", { key: "b", className: "flex items-center gap-1" }, [
      h(
        "button",
        {
          key: "p",
          type: "button",
          disabled: page <= 1,
          onClick: () => onPage(Math.max(1, page - 1)),
          className:
            "flex items-center gap-1 rounded-xl border border-slate-300/70 bg-white/50 px-2.5 py-1.5 text-xs font-medium hover:bg-white/70 disabled:opacity-40 dark:border-white/10 dark:bg-white/5 dark:hover:bg-white/10"
        },
        [h(ChevronLeft, { key: "i", className: "h-3.5 w-3.5" }), "Prev"]
      ),
      h(
        "button",
        {
          key: "n",
          type: "button",
          disabled: page >= pages,
          onClick: () => onPage(Math.min(pages, page + 1)),
          className:
            "flex items-center gap-1 rounded-xl border border-slate-300/70 bg-white/50 px-2.5 py-1.5 text-xs font-medium hover:bg-white/70 disabled:opacity-40 dark:border-white/10 dark:bg-white/5 dark:hover:bg-white/10"
        },
        ["Next", h(ChevronRight, { key: "i", className: "h-3.5 w-3.5" })]
      )
    ])
  ]);
}

function categoryLabel(v) {
  return REPORT_CATEGORIES.find((c) => c.value === v)?.label || v;
}

/**
 * @param {{ variant: "buyer" | "vendor" }} props
 */
function ReportPanelInner({ variant }) {
  const { accessToken } = useAuth();
  const { toast } = useNotice();
  const [searchParams] = useSearchParams();

  const [category, setCategory] = useState("other");
  const [description, setDescription] = useState("");
  const [targetType, setTargetType] = useState("other");
  const [targetId, setTargetId] = useState("");
  const [submitErr, setSubmitErr] = useState("");
  const [submitting, setSubmitting] = useState(false);

  const [rows, setRows] = useState([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(1);
  const [listNonce, setListNonce] = useState(0);
  const [listErr, setListErr] = useState("");
  const limit = 15;

  const backHref = variant === "vendor" ? "/vendor/dashboard" : "/";
  const backLabel = variant === "vendor" ? "Vendor dashboard" : "Home";

  useEffect(() => {
    const p = searchParams.get("product");
    const o = searchParams.get("order");
    const u = searchParams.get("user");
    if (p) {
      setTargetType("product");
      setTargetId(p);
    } else if (o) {
      setTargetType("order");
      setTargetId(o);
    } else if (u) {
      setTargetType("user");
      setTargetId(u);
    }
  }, [searchParams]);

  useEffect(() => {
    if (!accessToken) return;
    let cancelled = false;
    setListErr("");
    (async () => {
      try {
        const qs = new URLSearchParams({ page: String(page), limit: String(limit) });
        const d = await apiFetch(`/api/reports/me?${qs.toString()}`, {
          headers: { Authorization: `Bearer ${accessToken}` }
        });
        if (!cancelled) {
          setRows(d.reports || []);
          setTotal(d.total || 0);
        }
      } catch (ex) {
        if (!cancelled) setListErr(ex.message || "Could not load your reports.");
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [accessToken, page, listNonce]);

  const onSubmit = async (e) => {
    e.preventDefault();
    setSubmitErr("");
    if (!accessToken) return;
    if (String(description).trim().length < 10) {
      setSubmitErr("Please describe what happened in at least 10 characters so admins can review.");
      return;
    }
    setSubmitting(true);
    try {
      await apiFetch("/api/reports", {
        method: "POST",
        headers: { Authorization: `Bearer ${accessToken}` },
        json: {
          category,
          description: description.trim(),
          targetType,
          targetId: targetId.trim() || undefined
        }
      });
      toast("Report submitted. Our team will review it.", { variant: "success" });
      setDescription("");
      setCategory("other");
      setTargetType("other");
      setTargetId("");
      setPage(1);
      setListNonce((n) => n + 1);
    } catch (ex) {
      setSubmitErr(ex.message || "Could not submit report.");
    } finally {
      setSubmitting(false);
    }
  };

  const catOptions = REPORT_CATEGORIES.map((c) => h("option", { key: c.value, value: c.value }, c.label));
  const tgtOptions = TARGET_TYPES.map((t) => h("option", { key: t.value, value: t.value }, t.label));

  return h("div", { className: "mx-auto max-w-5xl px-4 py-8 sm:px-6" }, [
    h("div", { key: "nav", className: "mb-6" }, [
      h(
        Link,
        {
          to: backHref,
          className: "text-sm font-medium text-sky-600 hover:underline dark:text-sky-300"
        },
        `← ${backLabel}`
      ),
      h("div", { key: "hd", className: "mt-4 flex items-start gap-3" }, [
        h(
          "div",
          {
            className:
              "flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl bg-amber-500/20 text-amber-700 dark:bg-amber-500/15 dark:text-amber-200"
          },
          h(AlertTriangle, { className: "h-6 w-6" })
        ),
        h("div", { className: "min-w-0" }, [
          h("h1", { className: "font-display text-2xl font-bold text-slate-900 dark:text-white" }, "Reports & safety"),
          h(
            "p",
            { className: "mt-1 text-sm text-slate-600 dark:text-slate-400" },
            "Tell admins about scams, unsafe listings, or abuse. This matches what moderators see under Reports & complaints."
          )
        ])
      ])
    ]),

    h(GlassPanel, { key: "form", className: "mb-6" }, [
      h("h2", { className: "text-lg font-semibold text-slate-900 dark:text-white" }, "Submit a report"),
      h("p", { className: "mt-1 text-sm text-slate-500 dark:text-slate-400" }, "Be specific and factual. False reports may affect your account."),
      h(
        "form",
        { className: "mt-4 space-y-4", onSubmit },
        [
          h("div", { key: "r1", className: "grid gap-4 sm:grid-cols-2" }, [
            h(
              Field,
              { label: "Category" },
              h(SelectInput, { value: category, onChange: (e) => setCategory(e.target.value), required: true }, catOptions)
            ),
            h(
              Field,
              { label: "Related to" },
              h(SelectInput, { value: targetType, onChange: (e) => setTargetType(e.target.value), required: true }, tgtOptions)
            )
          ]),
          targetType !== "other"
            ? h(Field, { key: "tid", label: "Product / order / user ID (optional)" }, h(TextInput, {
                value: targetId,
                onChange: (e) => setTargetId(e.target.value),
                placeholder: "Paste the ID if you have it",
                className: "font-mono text-sm"
              }))
            : null,
          h(Field, { key: "desc", label: "What happened?" }, h(TextArea, {
            value: description,
            onChange: (e) => setDescription(e.target.value.slice(0, 4000)),
            rows: 5,
            required: true,
            placeholder: "Include dates, order or listing links, message context, and any evidence (min. 10 characters).",
            className: "min-h-[120px]"
          })),
          h("p", { key: "cnt", className: "text-right text-xs text-slate-500" }, `${description.length}/4000`),
          submitErr ? h(InlineNotice, { key: "err", variant: "error", onDismiss: () => setSubmitErr("") }, submitErr) : null,
          h(
            Button,
            { key: "sub", type: "submit", loading: submitting, className: "w-full sm:w-auto" },
            [h(Send, { key: "i", className: "h-4 w-4" }), "Send report"]
          )
        ].filter(Boolean)
      )
    ]),

    h("h2", { key: "list-h", className: "mb-3 text-lg font-semibold text-slate-900 dark:text-white" }, "Your reports"),
    listErr ? h(InlineNotice, { key: "le", variant: "error", onDismiss: () => setListErr("") }, listErr) : null,
    h(
      GlassCard,
      { key: "tbl", className: "!overflow-x-auto !p-0" },
      h("table", { className: "w-full min-w-[720px] text-left text-sm" }, [
        h(
          "thead",
          { className: "bg-white/30 text-xs uppercase text-slate-500 dark:bg-white/5 dark:text-slate-400" },
          h("tr", null, [
            h("th", { className: "px-4 py-3" }, "ID"),
            h("th", { className: "px-4 py-3" }, "Type"),
            h("th", { className: "px-4 py-3" }, "Target"),
            h("th", { className: "px-4 py-3" }, "Status"),
            h("th", { className: "px-4 py-3" }, "Submitted"),
            h("th", { className: "px-4 py-3" }, "Details")
          ])
        ),
        h(
          "tbody",
          { className: "divide-y divide-white/10" },
          rows.length === 0
            ? h(
                "tr",
                { key: "e" },
                h("td", { colSpan: 6, className: "px-4 py-12 text-center text-sm text-slate-500" }, "You have not submitted any reports yet.")
              )
            : rows.map((r) =>
                h(
                  "tr",
                  { key: r.id, className: "align-top hover:bg-white/5" },
                  [
                    h("td", { className: "px-4 py-3 font-mono text-xs" }, shortId(r.id)),
                    h("td", { className: "px-4 py-3 text-slate-700 dark:text-slate-200" }, categoryLabel(r.category)),
                    h("td", { className: "px-4 py-3 text-slate-500" }, [
                      h("div", { key: "t", className: "capitalize" }, r.targetType),
                      r.targetId
                        ? h("div", { key: "i", className: "mt-0.5 font-mono text-[10px] text-slate-400" }, String(r.targetId).slice(-12))
                        : null
                    ].filter(Boolean)),
                    h("td", { className: "px-4 py-3" }, h(Badge, { tone: reportStatusTone(r.status) }, r.status.replace(/_/g, " "))),
                    h("td", { className: "px-4 py-3 text-xs text-slate-500" }, fmtDate(r.createdAt)),
                    h(
                      "td",
                      { className: "max-w-[280px] px-4 py-3 text-xs text-slate-600 dark:text-slate-300" },
                      [
                        h("p", { key: "d", className: "line-clamp-4 whitespace-pre-wrap break-words" }, r.description),
                        r.adminNote
                          ? h("p", { key: "n", className: "mt-2 rounded-lg border border-sky-500/20 bg-sky-500/10 p-2 text-sky-900 dark:text-sky-100" }, [
                              h("span", { key: "l", className: "font-semibold" }, "Admin: "),
                              r.adminNote
                            ])
                          : null
                      ].filter(Boolean)
                    )
                  ]
                )
              )
        )
      ])
    ),
    h(ReportsPager, { key: "pg", page, total, limit, onPage: setPage })
  ]);
}

export function BuyerReportsPage() {
  const [cartOpen, setCartOpen] = useState(false);
  return h(f, null, [
    h(
      BuyerLayout,
      { key: "layout", onOpenCart: () => setCartOpen(true), hideSearch: true, title: "Reports" },
      h(ReportPanelInner, { key: "panel", variant: "buyer" })
    ),
    h(CartDrawer, { key: "cart", open: cartOpen, onClose: () => setCartOpen(false) })
  ]);
}

export function VendorReportsPage() {
  return h(ReportPanelInner, { variant: "vendor" });
}
